CREATE UNIQUE INDEX fixture_mkt_day ON public.mkt_metriche_giorno(service_client_id,giorno);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('test.uid',true),'')::uuid$$;
CREATE FUNCTION public.is_super_admin() RETURNS boolean LANGUAGE sql STABLE AS $$SELECT coalesce(current_setting('test.super',true),'off')='on'$$;
-- Helper non modificato dalla migrazione: valore fisso solo nella fixture isolata.
CREATE FUNCTION public.mkt_spesa_awareness(uuid,date,date) RETURNS numeric LANGUAGE sql STABLE AS $$SELECT 0::numeric$$;
CREATE FUNCTION public.mkt_soglia_di(uuid,date) RETURNS TABLE(cpl_target_effettivo numeric,cpl_giallo_effettivo numeric,cpl_rosso_effettivo numeric,fattore_stagionale numeric,moltiplicatore_zero_giallo numeric,moltiplicatore_zero_rosso numeric) LANGUAGE sql STABLE AS $$SELECT 100::numeric,150::numeric,200::numeric,1::numeric,2::numeric,3::numeric$$;
